}
GardenSoilpHTesterMaker.ironStock=14; GardenSoilpHTesterMaker.bronzeStock=12; GardenSoilpHTesterMaker.woodStock=12; GardenSoilpHTesterMaker.leatherStock=8; GardenSoilpHTesterMaker.silverStock=8; GardenSoilpHTesterMaker.goldStock=6; GardenSoilpHTesterMaker.jewelStock=4; GardenSoilpHTesterMaker.pearlStock=4
GardenSoilpHTesterMaker.productStock = {}; GardenSoilpHTesterMaker.buildings = {}; GardenSoilpHTesterMaker.maker = nil; GardenSoilpHTesterMaker.activeMaking = {}; GardenSoilpHTesterMaker.totalProducts = 0; GardenSoilpHTesterMaker.dayTimer = 0
function GardenSoilpHTesterMaker.init() GardenSoilpHTesterMaker.ironStock=14; GardenSoilpHTesterMaker.bronzeStock=12; GardenSoilpHTesterMaker.woodStock=12; GardenSoilpHTesterMaker.leatherStock=8; GardenSoilpHTesterMaker.silverStock=8; GardenSoilpHTesterMaker.goldStock=6; GardenSoilpHTesterMaker.jewelStock=4; GardenSoilpHTesterMaker.pearlStock=4; GardenSoilpHTesterMaker.productStock={}; GardenSoilpHTesterMaker.buildings={}; GardenSoilpHTesterMaker.maker=nil; GardenSoilpHTesterMaker.activeMaking={}; GardenSoilpHTesterMaker.totalProducts=0; GardenSoilpHTesterMaker.dayTimer=0; print("[GardenSoilpHTesterMaker] Royal Garden Soil pH Tester Maker System initialized (6 products, 4 buildings)") end
function GardenSoilpHTesterMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GardenSoilpHTesterMaker.maker={name=n or ("Merilnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Merilnik najet: %s (spretnost: %d)",GardenSoilpHTesterMaker.maker.name,s),"success") end; return true end
function GardenSoilpHTesterMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GardenSoilpHTesterMaker.build(id) local ok,e=GardenSoilpHTesterMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GardenSoilpHTesterMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GardenSoilpHTesterMaker.getQualityBonus() local b=0; for _,bd in ipairs(GardenSoilpHTesterMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GardenSoilpHTesterMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GardenSoilpHTesterMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GardenSoilpHTesterMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GardenSoilpHTesterMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GardenSoilpHTesterMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GardenSoilpHTesterMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GardenSoilpHTesterMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GardenSoilpHTesterMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GardenSoilpHTesterMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GardenSoilpHTesterMaker.buildings==0 then return false,"Potrebna merilna delavnica" end; if not GardenSoilpHTesterMaker.maker then return false,"Potreben merilnik" end; return true end
function GardenSoilpHTesterMaker.make(pt,qty) qty=qty or 1; local ok,e=GardenSoilpHTesterMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GardenSoilpHTesterMaker.ironStock=GardenSoilpHTesterMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GardenSoilpHTesterMaker.bronzeStock=GardenSoilpHTesterMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GardenSoilpHTesterMaker.woodStock=GardenSoilpHTesterMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GardenSoilpHTesterMaker.leatherStock=GardenSoilpHTesterMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GardenSoilpHTesterMaker.silverStock=GardenSoilpHTesterMaker.silverStock-d.silverCost*qty end; if d.goldCost then GardenSoilpHTesterMaker.goldStock=GardenSoilpHTesterMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GardenSoilpHTesterMaker.jewelStock=GardenSoilpHTesterMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GardenSoilpHTesterMaker.pearlStock=GardenSoilpHTesterMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GardenSoilpHTesterMaker.maker then t=math.max(1,t-math.floor(GardenSoilpHTesterMaker.maker.skill/13)) end; table.insert(GardenSoilpHTesterMaker.activeMaking,{id="gardensoilphtester_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GardenSoilpHTesterMaker.completeMaking(m) local q=1.0+(GardenSoilpHTesterMaker.getQualityBonus()/100); if GardenSoilpHTesterMaker.maker then q=q+(GardenSoilpHTesterMaker.maker.skill/140) end; q=math.min(2.5,q); GardenSoilpHTesterMaker.productStock[m.productType]=(GardenSoilpHTesterMaker.productStock[m.productType] or 0)+m.quantity; GardenSoilpHTesterMaker.totalProducts=GardenSoilpHTesterMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GardenSoilpHTesterMaker.maker then GardenSoilpHTesterMaker.maker.itemsMade=GardenSoilpHTesterMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GardenSoilpHTesterMaker.maker.skill=math.min(100,GardenSoilpHTesterMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Merilec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"gardensoilphtester.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GardenSoilpHTesterMaker.update(dt) if not _G.state then return end; GardenSoilpHTesterMaker.dayTimer=GardenSoilpHTesterMaker.dayTimer+dt; if GardenSoilpHTesterMaker.dayTimer>=30 then GardenSoilpHTesterMaker.dayTimer=0; for i=#GardenSoilpHTesterMaker.activeMaking,1,-1 do local m=GardenSoilpHTesterMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GardenSoilpHTesterMaker.completeMaking(m); table.remove(GardenSoilpHTesterMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GardenSoilpHTesterMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GardenSoilpHTesterMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GardenSoilpHTesterMaker.getStats() return {ironStock=GardenSoilpHTesterMaker.ironStock,bronzeStock=GardenSoilpHTesterMaker.bronzeStock,woodStock=GardenSoilpHTesterMaker.woodStock,leatherStock=GardenSoilpHTesterMaker.leatherStock,silverStock=GardenSoilpHTesterMaker.silverStock,goldStock=GardenSoilpHTesterMaker.goldStock,jewelStock=GardenSoilpHTesterMaker.jewelStock,pearlStock=GardenSoilpHTesterMaker.pearlStock,productStock=GardenSoilpHTesterMaker.productStock,numBuildings=#GardenSoilpHTesterMaker.buildings,hasMaker=GardenSoilpHTesterMaker.maker~=nil,makerName=GardenSoilpHTesterMaker.maker and GardenSoilpHTesterMaker.maker.name or "—",makerSkill=GardenSoilpHTesterMaker.maker and GardenSoilpHTesterMaker.maker.skill or 0,activeMaking=#GardenSoilpHTesterMaker.activeMaking,totalProducts=GardenSoilpHTesterMaker.totalProducts} end
